// Package domain holds the service's domain kernel (generated by gherkin-ai).
package domain

import (
	"errors"
	"time"
)

// ErrValidation is wrapped by every domain validation failure.
var ErrValidation = errors.New("domain validation error")

// State is an aggregate state; EventType a domain event type.
type State string

type EventType string

type Command struct {
	ID      string
	Payload map[string]any
}

type DomainEvent struct {
	Type        EventType
	AggregateID string
	Version     int64
	OccurredOn  time.Time
	Payload     map[string]any
}
